using System.Collections.Generic;
using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RerollAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Reroll Action")]
public class RerollAction : ChooseDiceAction
{
	[Header("References")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		int diceInHandAmountNotLocked = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmountNotLocked();
		List<GameObject> list = new List<GameObject>();
		list.AddRange(currentCompanions.ActiveCompanions);
		list.AddRange(currentCorruptedAnimals.activeCorruptedAnimals);
		int num = 0;
		for (int i = 0; i < list.Count; i++)
		{
			num += list[i].GetComponent<UnitsDiceActivation>().GetDiceInstancesToRoll(ignoreDisabledActions: true).Count;
		}
		bool flag = false;
		if (diceOwnerEnum != 0)
		{
			if (diceInHandAmountNotLocked == 0 && num <= 1)
			{
				flag = true;
			}
		}
		else if (playerHand)
		{
			if (diceInHandAmountNotLocked <= 1 && num == 0)
			{
				flag = true;
			}
		}
		else if (diceInHandAmountNotLocked == 0 && num == 0)
		{
			flag = true;
		}
		if (flag)
		{
			return false;
		}
		if (diceOwnerEnum != 0)
		{
			return true;
		}
		bool flag2 = false;
		if (!flag2)
		{
			for (int j = 0; j < currentCorruptedAnimals.activeCorruptedAnimals.Count; j++)
			{
				if (currentCorruptedAnimals.activeCorruptedAnimals[j].GetComponent<CorruptedAnimalEffects>().IsStunningAuraActive())
				{
					flag2 = true;
				}
			}
		}
		return !flag2;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return !diceInstance.ActionFace.BattleAction.Locked;
	}

	public override int GetNonOverrideDiceToSelectAmount(ActionFace actionFace)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.CurrentChooseDiceActionInstanceReference.Value.DiceOwnerEnum == DiceOwnerEnum.PLAYER && playerGameObjectReference.value.GetComponent<PlayerEffects>().IsPlayerStunnedEffect(activateFeedback: false))
		{
			return 1;
		}
		return actionFace.ModifiedActionValue;
	}

	public override void ActionSelected(int amount)
	{
		int amount2 = amount;
		if (ReferenceSingleton<BattleHandler>.Instance.CurrentChooseDiceActionInstanceReference.Value.DiceOwnerEnum == DiceOwnerEnum.PLAYER && playerGameObjectReference.value.GetComponent<PlayerEffects>().IsPlayerStunnedEffect(activateFeedback: true))
		{
			amount2 = 1;
		}
		base.ActionSelected(amount2);
		ResetVariables();
	}

	public void ExternalCast(List<DiceInstance> diceInstances, RollDiceActionType rollDiceActionType, GameObject source)
	{
		ResetVariables();
		diceList.AddRange(diceInstances);
		Cast(rollDiceActionType, source);
	}

	public override void Cast(GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			playerGameObjectReference.value.GetComponent<PlayerEffects>().IsPlayerStunnedEffectDecreaseEffect();
		}
		Cast(RollDiceActionType.REROLL, source);
	}

	private void Cast(RollDiceActionType rollDiceActionType, GameObject source, bool bottledAuroraReroll = false)
	{
		if (rollDiceActionType == RollDiceActionType.REROLL && diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count; i++)
			{
				DiceInstance diceInstance = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices[i];
				diceInstance.SetOriginalPositionAsCurrentPosition();
				diceList.Add(diceInstance);
			}
		}
		if (rollDiceActionType == RollDiceActionType.REROLL || rollDiceActionType == RollDiceActionType.EXTERNALREROLL)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateRerollOmens(diceList);
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 5, delegate
		{
			_ = ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance;
			if (rollDiceActionType == RollDiceActionType.REROLL)
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AddReroledDiceAmount(diceList.Count);
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DiceInstanceRerolledListAndCheckAchievement(diceList);
				if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
				{
					List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
					for (int j = 0; j < activeCorruptedAnimals.Count; j++)
					{
						activeCorruptedAnimals[j].GetComponent<CorruptedAnimalEffects>().OnRerollEffects(diceList.Count);
					}
				}
				ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().OnRerollEffects(diceList.Count);
				for (int k = 0; k < diceList.Count; k++)
				{
					diceList[k].ToggleHideDiceFace(value: false);
				}
			}
			RollDice(rollDiceActionType, bottledAuroraReroll);
		});
	}

	public void RollDice(RollDiceActionType rollDiceActionType, bool bottledAuroraReroll)
	{
		if (rollDiceActionType != RollDiceActionType.NONREROLL && rollDiceActionType != RollDiceActionType.REARM)
		{
			diceList.RemoveAll((DiceInstance dieInstance) => dieInstance.DiceState == DiceState.Rolling || dieInstance.DiceState == DiceState.FinishedRolling);
		}
		for (int i = 0; i < diceList.Count; i++)
		{
			if (rollDiceActionType == RollDiceActionType.REROLL || rollDiceActionType == RollDiceActionType.REARM || rollDiceActionType == RollDiceActionType.EXTERNALREROLL || rollDiceActionType == RollDiceActionType.NONREROLL)
			{
				diceList[i].SetupDiceToRoll();
			}
			else
			{
				diceList[i].SetupDiceRollRepairAction();
			}
		}
		ReferenceSingleton<DiceRollingHandler>.Instance.RollDice(diceList, bottledAuroraReroll);
	}

	public void RerollHandOmenCast()
	{
		ResetVariables();
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.1f, delegate
		{
			Cast(RollDiceActionType.REROLL, null, bottledAuroraReroll: true);
		});
	}
}
